namespace MTWalk.Walking;

/// <summary>
/// Represents a walker that executes the terminal for each window generated by the provided windowing strategy.
/// </summary>
/// <param name="windowingStrategy"></param>
/// <remarks>
/// https://www.mql5.com/en/articles/3279
/// </remarks>

class Walker(IWindowingStrategy windowingStrategy,
             IWalkDirectoryProvider directoryProvider,
             IOptimizationService optimizationService,
             IForwardService forwardService) : IWalker
{
    public async Task Start(WalkRequest walkRequest,
                            IProgress<WalkReport>? progress = default,
                            CancellationToken token = default)
    {
        var tester = walkRequest.Tester;
        var walkDirectory = directoryProvider.GetWalkDirectory(tester);
        var parametersFile = walkDirectory.GetWalkParametersFile();
        if (walkRequest.Inputs.SetFileContent is null ||
            walkRequest.Inputs.SetFileContent.Contains("|Y") is false)
        {
            throw new NoOptimizationParametersSelectedException();
        }
        parametersFile.Write(walkRequest.Inputs.SetFileContent);

        var deposit = tester.Deposit;
        var windows = windowingStrategy.GetWindows(tester.Start, tester.End, walkRequest.Windowing);
        foreach (var window in windows)
        {
            var optimizationResult = await optimizationService.RunAsync(testerRequest: tester,
                                                                        timeRange: window.Optimization,
                                                                        directory: walkDirectory,
                                                                        expertParameters: parametersFile.RelativeToTesterPath,
                                                                        deposit: deposit,
                                                                        token: token);

            var forwardResult = await forwardService.RunAsync(testerRequest: tester,
                                                              timeRange: window.Forward,
                                                              directory: walkDirectory,
                                                              expertParameters: optimizationResult.BestSetFile.RelativeToDataFolderPath,
                                                              deposit: deposit,
                                                              token: token);
            progress?.Report(new(window, forwardResult.Report));
            deposit = forwardResult.Balance;
        }
    }
}
